(()=>{const search=document.getElementById('master-search'),buttons=[...document.querySelectorAll('[data-filter]')],cards=[...document.querySelectorAll('.master')];let category='all';const groups={iran:[1,2,4,6,7,8],world:[0,1,2,3,5,8,9,12],art:[10,11]};function apply(){const query=search.value.trim();for(const [index,card] of cards.entries()){const text=card.textContent;card.hidden=!(text.includes(query)&&(category==='all'||groups[category].includes(index)))}}for(const button of buttons)button.addEventListener('click',()=>{category=button.dataset.filter;buttons.forEach(b=>b.classList.toggle('selected',b===button));apply()});search.addEventListener('input',apply)})();
(()=>{const week=[['شنبه',['هنگ درام','داربوکا','جیمبی','دف','ارف','ویولن','نقاشی','عکاسی و فیلم‌برداری']],['یکشنبه',['دف','کاخن','کالیمبا','موسیقی کودک','سازشناسی کودکان']],['دوشنبه',['ویولن','ترومپت','آهنگسازی','تنظیم','صدابرداری','فن بیان','نقاشی','دف','دی جی']],['سه‌شنبه',['گیتار','سلفژ','آواز','کلارینت','ترومپت','نی','ویولن','تئوری موسیقی']],['چهارشنبه',['جیمبی','پیانو','درام','ملودیکا','کیبورد','ویولن','ترومپت','نقاشی']],['پنجشنبه',['سنتور','تار','سه‌تار','عود','دف','تنبک','ویولن','موسیقی کودک']]];const icons={'گیتار':'♩','ویولن':'𝄞','پیانو':'▥','درام':'◎','نقاشی':'✎','دف':'◉','نی':'♮','ترومپت':'♫','عکاسی و فیلم‌برداری':'▣'};const tabs=document.getElementById('day-tabs');function select(index){const [day,courses]=week[index];tabs.innerHTML=week.map(([name],i)=>`<button role="tab" aria-selected="${i===index}" class="${i===index?'chosen':''}" data-day="${i}"><span>${String(i+1).replace(/\d/g,d=>'۰۱۲۳۴۵۶۷۸۹'[d])}</span>${name}<b>←</b></button>`).join('');document.getElementById('day-title').textContent=day+'‌های آوای هزاردستان';document.getElementById('day-count').textContent=courses.length.toLocaleString('fa-IR')+' رشته';document.getElementById('day-courses').innerHTML=courses.map((name,i)=>`<a href="#contact" class="day-course" style="--order:${i}"><span class="course-symbol">${icons[name]||'♫'}</span><div><small>کلاس ${String(i+1).replace(/\d/g,d=>'۰۱۲۳۴۵۶۷۸۹'[d])}</small><h4>${name}</h4></div><span class="course-corner">↗</span></a>`).join('');tabs.querySelectorAll('button').forEach(b=>b.onclick=()=>select(Number(b.dataset.day)));}select(0)})();
